import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"ADR 003 · Workflow ownership","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/003-workflow-ownership.md","filePath":"decisions/003-workflow-ownership.md","lastUpdated":1794376220000}'),n={name:"decisions/003-workflow-ownership.md"};function i(s,e,d,c,l,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-003-·-workflow-ownership" tabindex="-1">ADR 003 · Workflow ownership <a class="header-anchor" href="#adr-003-·-workflow-ownership" aria-label="Permalink to &quot;ADR 003 · Workflow ownership&quot;">​</a></h1><p><strong>Status:</strong> Single-owner rule adopted for the draft; execution engine open. <strong>Date:</strong> November 5, 2026.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Parsing, chunking, NLP, NER, entity resolution, relationship extraction, indexing, and augmentation have different dependencies and resource requirements. Work must recover from failures without promoting stale artifacts or blocking usable search.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Model ingestion as a DAG over versioned artifacts. One durable orchestrator owns readiness, retries, attempts, timeouts, cancellation, and dependency progression. Evaluate Dagster and Temporal before selecting a runtime. NATS/JetStream carries relevant system events and durable work only where that does not duplicate orchestration ownership.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The workflow engine may use its own task queues and state database. SQLite retrieval storage does not automatically become workflow control storage. Jobs reference artifacts and fingerprints rather than transporting entire documents in broker messages.</p><p>Publish readiness after committed outputs. Use idempotent writes, current-version checks, outbox publication, and reconciliation. Acknowledgments and exactly-once messaging features do not imply exactly-once model execution.</p><h2 id="alternatives-and-tradeoffs" tabindex="-1">Alternatives and tradeoffs <a class="header-anchor" href="#alternatives-and-tradeoffs" aria-label="Permalink to &quot;Alternatives and tradeoffs&quot;">​</a></h2><p>Pure event choreography distributes dependency logic across consumers and makes joins, cancellation, and recovery harder to inspect. A custom scheduler would require implementing durable leases, fencing, retries, dependency joins, and upgrades. It needs a concrete justification before adoption.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Kill a worker before and after commit; redeliver a task; replace or delete a source mid-run; correct an entity merge; interrupt a model call; and verify that completed independent artifacts remain usable. Compare operational recovery and incremental reprocessing with representative document workloads. See <a href="/knowledge-lab/architecture/ingestion">ingestion</a>.</p>',13)])])}const f=a(n,[["render",i]]);export{h as __pageData,f as default};
